pub fn set_loop(&mut self, range: Option<TimelineLoop>) -> Result<(), TimelineLoopError> {
    if let Some(r) = range
        && (r.start < TimelineTick::ZERO || r.start >= r.end || r.end > self.duration)
    {
        return Err(TimelineLoopError);
    }
    self.loop_range = range;
    Ok(())
}
